@Repository
public class OrderProcessingService {

    private final JdbcTemplate jdbcTemplate;
    private final MongoTemplate mongoTemplate;

    public OrderProcessingService(JdbcTemplate jdbcTemplate, MongoTemplate mongoTemplate) {
        this.jdbcTemplate = jdbcTemplate;
        this.mongoTemplate = mongoTemplate;
    }

    @Transactional
    public void processSqlOrder(Long orderId, BigDecimal amount) {
        // SQL enforces ACID invariants across relational tables
        String sql = "UPDATE accounts SET balance = balance - ? WHERE id = ?";
        jdbcTemplate.update(sql, amount, 1L);
    }

    public void saveNoSqlLog(AuditLogDocument log) {
        // NoSQL document store optimizes for high-speed append and flexible schema
        mongoTemplate.save(log, "audit_logs");
    }
}
